-- Data Checks-- row countsselect 'customers' as titel, count(*) as numbersfrom customersunion allselect 'subscriptions', count(*)from subscriptionsunion allselect 'payments', count(*)from paymentsunion allselect 'usage_monthly', count(*)from usage_monthlyunion allselect 'support_tickets', count(*)from support_tickets;-- Orphans records (all should be 0)select count(*) as orphan_subscriptionsfrom subscriptions s         left join customers c on s.customer_id = c.customer_idwhere c.customer_id is null;select count(*) as orphan_paymentsfrom payments p         left join subscriptions s on p.subscription_id = s.subscription_idwhere s.subscription_id is null;-- Logic Checks (all should be 0)select count(*) as end_before_startfrom subscriptionswhere end_date < start_date;select count(*) as cancelled_woithout_endfrom subscriptionswhere status = 'Cancelled' and end_date is null ;select count(*) as seats_over_plan_limitfrom subscriptions s join plans  p on s.plan_id = p.plan_idwhere s.seats > p.max_seats;-- Q1. Overall churn rateselect count(*)                                             as total_sub,       sum(status = 'Cancelled')                            as churned,       round(100 * sum(status = 'Cancelled') / count(*), 1) as churn_pctfrom subscriptions;-- Q2. Churn by planselect p.plan_name,       count(*)                                             as subs,       sum(status = 'Cancelled')                            as cancelled_subs,       round(100 * sum(status = 'Cancelled') / count(*), 1) as churn_pctfrom subscriptions s         join plans p on s.plan_id = p.plan_idgroup by p.plan_nameorder by churn_pct desc;-- Q3. Churn by acquisition channelselect c.acquisition_channel,       count(*)                                             as subs,       sum(status = 'Cancelled') as cancelled_subs,       round(100 * sum(status = 'Cancelled') / count(*), 1) as churn_pctfrom subscriptions s         join customers c on s.customer_id = c.customer_idgroup by c.acquisition_channelorder by churn_pct desc;-- Q4. Current MRR by plan (active subscriptions)select p.plan_name, count(*) as active_subs, round(sum(s.mrr), 0) as mrrfrom subscriptions s         join plans p on s.plan_id = p.plan_idwhere status  = 'Active'group by p.plan_nameorder by  mrr desc ;-- Q5. Monthly MRR trend (subscription active during the month)WITH RECURSIVE months AS (SELECT DATE('2022-01-01') AS m                          UNION ALL                          SELECT DATE_ADD(m, INTERVAL 1 MONTH)                          FROM months                          WHERE m < '2025-12-01')SELECT m AS month, ROUND(SUM(s.mrr), 0) AS mrrFROM months         JOIN subscriptions s              ON s.start_date <= LAST_DAY(m)                  AND (s.end_date IS NULL OR s.end_date >= m)GROUP BY mORDER BY m;-- Q6. Top cancel reasonsselect cancel_reason , count(*) as total_numfrom subscriptionswhere cancel_reason is not nullgroup by cancel_reasonorder by total_num desc ;-- Q7. Failed-payment revenue loss by monthselect DATE_FORMAT(payment_date, '%Y-%m') as month, count(*) as faild, round(sum(amount), 0) as lost_revenuefrom paymentswhere payment_status = 'Failed'group by 1order by 1;-- Q8. Does usage drop before cancellation? (avg active-user ratio: last 3 months vs earlier)with ranked as (select s.subscription_id,                       u.active_users / s.seats                                                  as ratio,                       row_number() over (partition by s.subscription_id order by u.month desc ) as rn                from subscriptions s                         join usage_monthly u on s.customer_id = u.customer_id                where s.status = 'Cancelled')select case when rn <= 3 then 'Last 3 month' else 'earlier' end as period,    round(avg(ratio),3) as avg_active_ratiofrom rankedgroup by 1;-- Q9. Support experience vs churnselect s.status, round(avg(t.satisfaction_score), 2) as avg_cast, round(avg(t.resolution_hours),1) as avg_resolution_hrsfrom support_tickets t         join subscriptions s on t.customer_id = s.customer_idgroup by s.status